#include "reference/cuda_spai_gate3.hpp"
#include "cuda_spai_allocation_audit.hpp"
#define BSPAI_CUDA_SPAI_HELPERS_ONLY
#include "test_cuda_spai.cpp"
#undef BSPAI_CUDA_SPAI_HELPERS_ONLY
namespace {
bspai::CsrMatrix band(std::size_t n,double diagonal){std::vector<bspai::Entry> e;for(std::size_t i=0;i<n;++i){const double scale=std::ldexp(1.0,static_cast<int>(i%5)-2);e.push_back({i,i,diagonal*scale});if(i)e.push_back({i,i-1,2*scale});if(i+1<n)e.push_back({i,i+1,scale});}return bspai::CsrMatrix::from_entries(n,n,e);}
void matrices(const bspai::CsrMatrix& a,const bspai::CsrMatrix& b){check(a.row_offsets()==b.row_offsets()&&a.column_indices()==b.column_indices(),"canonical sparse structure agrees");check(a.values().size()==b.values().size(),"canonical values count agrees");for(std::size_t i=0;i<std::min(a.values().size(),b.values().size());++i)check(near(a.values()[i],b.values()[i]),"canonical numeric values agree within frozen bound");}
void equivalent(const bspai::SpaiResult& a,const bspai::SpaiResult& b){check(a.status==b.status,"backend overall status");check(a.scaling==b.scaling,"scaling exact dyadic agreement");matrices(a.scaled_transpose,b.scaled_transpose);matrices(a.inverse,b.inverse);matrices(a.preconditioner,b.preconditioner);check(a.columns.size()==b.columns.size(),"all column diagnostics retained");for(std::size_t k=0;k<std::min(a.columns.size(),b.columns.size());++k){const auto& x=a.columns[k];const auto& y=b.columns[k];check(x.status==y.status&&x.pattern==y.pattern&&x.fits==y.fits&&x.growths==y.growths,"column status/pattern/work agreement");check(x.history.size()==y.history.size(),"fit history count");for(std::size_t h=0;h<std::min(x.history.size(),y.history.size());++h){const auto& f=x.history[h];const auto& g=y.history[h];check(f.pattern==g.pattern&&f.shadow==g.shadow&&f.candidates==g.candidates&&f.selected==g.selected,"full adaptive metadata agreement");check(near(f.residual,g.residual)&&near(f.full_residual,g.full_residual),"fit residual agreement");for(std::size_t j=0;j<std::min(f.coefficients.size(),g.coefficients.size());++j)check(near(f.coefficients[j],g.coefficients[j]),"fit coefficient agreement");for(std::size_t j=0;j<std::min(f.scores.size(),g.scores.size());++j)check(near(f.scores[j],g.scores[j]),"candidate score agreement");}}}
void sparse_residual(const bspai::SpaiResult& r,double epsilon){const auto& b=r.scaled_transpose;const auto bt=b.transpose();for(std::size_t k=0;k<r.columns.size();++k){const auto& c=r.columns[k];for(const auto& f:c.history){std::vector<long double> residual(b.rows(),0);residual[k]=-1;for(std::size_t j=0;j<f.pattern.size();++j){const auto col=f.pattern[j];for(auto at=bt.row_offsets()[col];at<bt.row_offsets()[col+1];++at)residual[bt.column_indices()[at]]+=static_cast<long double>(bt.values()[at])*f.coefficients[j];}check(near(norm(residual),f.full_residual),"independent sparse full B*m-e residual");for(std::size_t row=0;row<b.rows();++row)if(!std::binary_search(f.shadow.begin(),f.shadow.end(),row))check(residual[row]==0,"outside-shadow original residual exactly zero");}if(c.status==bspai::SpaiStatus::success)check(c.full_residual<=epsilon,"unchanged epsilon accepts completed fit");}}
void memory(const bspai::CsrMatrix& a,const bspai::CudaSpaiResult& r){const auto actual=validation::allocation_audit();const auto& t=r.telemetry;check(t.device_allocation_calls==actual.calls&&t.device_allocated_bytes==actual.total,"actual cudaMalloc calls/cumulative bytes match telemetry");check(t.peak_device_bytes==actual.peak&&t.max_single_allocation_bytes==actual.maximum,"actual live peak/largest allocation match telemetry");check(t.current_device_bytes==actual.current&&t.outstanding_device_allocations==actual.outstanding&&actual.current==0&&actual.outstanding==0,"all source allocations released normal return");check(t.nnz_b==a.values().size(),"B retains exact sparse nnz");check(t.sparse_b_bytes==(a.rows()+1)*8+a.values().size()*16,"B topology/value allocation exact");std::size_t solved=0;for(const auto& c:r.construction.columns)solved+=c.pattern.size();check(t.packed_output_bytes==solved*24,"packed N/P allocated by solved patterns not n squared");for(const auto& s:t.slot_memory){check(s.reduced_capacity_bytes<=s.max_rows*s.max_columns*8,"retained QR capacity bounded by actual reduced sizes");check(s.total_capacity_bytes>=s.reduced_capacity_bytes+s.workspace_capacity_bytes,"slot totals include retained reduced and queried vendor workspace");}std::cout<<"SPARSE_MEMORY n="<<a.rows()<<" nnz="<<a.values().size()<<" calls="<<actual.calls<<" cumulative="<<actual.total<<" peak="<<actual.peak<<" largest="<<actual.maximum<<" max_m="<<t.max_reduced_rows<<" max_q="<<t.max_pattern_columns<<" max_mq="<<t.max_reduced_elements<<" qr_workspace="<<t.max_qr_workspace_bytes<<" packed="<<t.packed_output_bytes<<'\n';}
}
int main(){try{std::cout<<std::setprecision(17);bspai::SpaiOptions o;o.epsilon=.3;o.alpha=5;o.beta=8;for(double diagonal:{8.,5.})for(std::size_t n:{16u,64u,256u,1024u}){const auto a=band(n,diagonal);const auto r=validation::audited_construct(a,o);check(r.construction.status==bspai::SpaiStatus::success,"progressive sparse matrix success");memory(a,r);sparse_residual(r.construction,o.epsilon);if(n<=256)equivalent(r.construction,bspai::construct_spai(a,o));if(n<=64)equivalent(r.construction,bspai::cuda_construct_spai_dense_reference(a,o).construction);if(n==16){audit_result(dense(a),r.construction,o.epsilon);structure(r.construction,o);emit_fits(r.construction,o.epsilon);}}
    const Dense tiny={{4,1,0},{2,5,1},{0,1,3}};o.epsilon=1e-12;o.alpha=2;auto a=matrix(tiny);auto r=validation::audited_construct(a,o);memory(a,r);equivalent(r.construction,bspai::cuda_construct_spai_dense_reference(a,o).construction);o.alpha=0;r=validation::audited_construct(a,o);memory(a,r);equivalent(r.construction,bspai::cuda_construct_spai_dense_reference(a,o).construction);
    o.alpha=3;for(const auto& bad:std::vector<Dense>{{{1,2},{1,2}},{{0,1},{1,1}},{{1e308L,1e-300L},{0,1}}}){r=validation::audited_construct(matrix(bad),o);check(r.construction.status!=bspai::SpaiStatus::success,"degenerate/range input explicit failure");check(validation::allocation_audit().current==0&&validation::allocation_audit().outstanding==0,"failure allocation cleanup");equivalent(r.construction,bspai::cuda_construct_spai_dense_reference(matrix(bad),o).construction);}
    bspai::IrOptions ir;ir.spai.epsilon=.3;ir.spai.alpha=5;const auto large=band(64,5);std::vector<double> truth(64);for(std::size_t i=0;i<truth.size();++i)truth[i]=static_cast<double>(static_cast<int>(i%7)-3)/4;const auto rhs=large.multiply(truth);const auto gpu=bspai::cuda_gpu_spai_gmres_ir(large,rhs,ir,truth);const auto cpu=bspai::spai_gmres_ir(large,rhs,ir,truth);solve_audit(dense(large),rhs,gpu);check(gpu.solver.status==cpu.status&&gpu.solver.converged,"larger end-to-end CPU/GPU success");for(std::size_t i=0;i<truth.size();++i)check(near(gpu.solver.solution[i],truth[i],1e-12L),"larger manufactured solution accuracy");
}catch(const std::exception& e){++failures;std::cerr<<"UNEXPECTED EXCEPTION: "<<e.what()<<'\n';}std::cout<<"Independent sparse GPU SPAI: "<<checks<<" checks, "<<failures<<" failures\n";return failures?1:0;}
